// Google Sheets API でスプレッドシート作成
// 実装: Google Drive API を使用
const config = {
  spreadsheet_title: 'RIO Metrics - Daily Content Analysis',
  spreadsheet_id: null, // 作成後に設定
  sheets: [
    {
      title: 'daily_metrics',
      headers: ['date', 'note_sales', 'note_views', 'threads_impressions', 'threads_clicks', 'wordpress_pv', 'wordpress_clicks', 'rakuten_sales', 'rakuten_views', 'amazon_clicks', 'amazon_conversions', 'brain_sales', 'cost_anthropic', 'cost_browser', 'owner_hours']
    },
    {
      title: 'note_data',
      headers: ['date', 'sales', 'views', 'conversion_rate']
    },
    {
      title: 'threads_data',
      headers: ['date', 'impressions', 'clicks', 'engagement_rate']
    },
    {
      title: 'wordpress_data',
      headers: ['date', 'pv', 'clicks', 'ctr']
    },
    {
      title: 'rakuten_data',
      headers: ['date', 'sales', 'views']
    },
    {
      title: 'amazon_data',
      headers: ['date', 'clicks', 'conversions']
    },
    {
      title: 'brain_data',
      headers: ['date', 'sales']
    }
  ]
};
return [{ json: config }];

// 作成したスプレッドシートの ID を抽出
const result = $input.first().json;
const config = $('Config Sheets Structure').first().json;

let spreadsheet_id = null;
let create_error = null;

if (result.spreadsheetId) {
  spreadsheet_id = result.spreadsheetId;
} else {
  create_error = 'spreadsheet_creation_failed';
}

return [{ json: {
  ...config,
  spreadsheet_id,
  create_error,
  spreadsheet_url: spreadsheet_id ? `https://docs.google.com/spreadsheets/d/${spreadsheet_id}/edit` : null
} }];

// 各シートのヘッダー行を入力
const d = $input.first().json;

if (!d.spreadsheet_id) {
  return [{ json: { ...d, note: 'スプレッドシート作成失敗のため、スキップ' } }];
}

// 複数のシートにヘッダー行を追加する HTTP リクエストを準備
const requests = d.sheets.map((sheet, idx) => ({
  updateCells: {
    range: {
      sheetId: idx,
      rowIndex: 0,
      columnIndex: 0
    },
    rows: [
      {
        values: sheet.headers.map(h => ({
          userEnteredValue: {
            stringValue: h
          },
          userEnteredFormat: {
            textFormat: { bold: true },
            backgroundColor: { red: 0.2, green: 0.2, blue: 0.2 }
          }
        }))
      }
    ],
    fields: 'userEnteredValue,userEnteredFormat'
  }
}));

return [{ json: { ...d, batch_update_requests: requests } }];

// 完了メッセージ
const d = $input.first().json;

const result = {
  status: 'COMPLETED',
  spreadsheet_id: d.spreadsheet_id,
  spreadsheet_url: d.spreadsheet_url,
  sheets_count: d.sheets.length,
  sheets_names: d.sheets.map(s => s.title),
  next_step: `n8n 環境変数に以下を設定してください:\nGOOGLE_SHEETS_METRICS_ID=${d.spreadsheet_id}`,
  note: 'セットアップ完了。401/602/603 で使用可能です。'
};

return [{ json: result }];
